import{_ as i,C as t,o as l,c as r,af as a,E as s,w as h}from"./chunks/framework.8iCprRBG.js";const _=JSON.parse('{"title":"Flushing the terminal","description":"","frontmatter":{},"headers":[],"relativePath":"docs/flush.md","filePath":"docs/flush.md"}'),c={name:"docs/flush.md"};function d(p,e,u,m,f,g){const n=t("MermaidDiagram"),o=t("ClientOnly");return l(),r("div",null,[e[0]||(e[0]=a(`<h1 id="flushing-the-terminal" tabindex="-1">Flushing the terminal <a class="header-anchor" href="#flushing-the-terminal" aria-label="Permalink to &quot;Flushing the terminal&quot;">​</a></h1><p>This page explains how you can implement an OOG without reading the memory. You may skip this if want to get to the good parts. I just think that it&#39;s good to explain this process to provide some context</p><h2 id="flush" tabindex="-1">Flush <a class="header-anchor" href="#flush" aria-label="Permalink to &quot;Flush&quot;">​</a></h2><p>The <code>flush</code> command dumps the contents of the terminal into <code>shell.txt</code>. It is a reserved keyword and it executes instantly.</p><div class="language-hackmud vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hackmud</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;flush</span></span>
<span class="line"><span>Window contents have been written to disk successfully.</span></span>
<span class="line"><span>C:\\Users\\Ruslan_Taranov\\AppData\\Roaming\\hackmud\\shell.txt</span></span></code></pre></div><p>Here&#39;s one way to use <code>flush</code> to sequentially execute commands</p>`,6)),s(o,null,{default:h(()=>[s(n,{code:"flowchart%20TD%0A%0Aa1%5BPress%20ESC%20to%20clear%20the%20command%20line%5D%0A--%3Ea2%5BType%20clear%2C%20press%20enter%2C%20wait%20a%20bit%5D%0A--%3Ea21%5BType%20a%20command%2C%20press%20enter%2C%20wait%20a%20bit%5D%0A--%3Ea4%5BType%20flush%5D%0A--%3Ea5%5BPress%20enter%5D%0A--%3Ea6%7BRead%20shell.txt.%20Did%20the%20file%20change%20and%20contains%20your%20command%3F%7D%0A%0Aa6--%3E%7CNo%7Ca5%0Aa6--%3E%7CYes%7Ca7%5BProcess%20the%20result%20of%20the%20command%5D--%3Ea1"})]),_:1}),e[1]||(e[1]=a(`<p>TODO: Provide a gif/video of the process</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>There are several problems with this approach.</p><p>Sometimes if the game lags or if you don&#39;t wait long enough you will end up with</p><div class="language-hackmud vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hackmud</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;your.scriptflush</span></span>
<span class="line"><span># or</span></span>
<span class="line"><span>&gt;&gt;clearyour.script</span></span>
<span class="line"><span># or some other variation</span></span></code></pre></div><p>If this happens, your script will not be executed and/or you will fail to get the output in a text file. You&#39;ll need to create timeout logic to escape these deadlocks. For example, if a <code>shell.txt</code> file doesn&#39;t update for long enough that means you are stuck somewhere. Where? You don&#39;t know and can&#39;t know. Your only way of communication with the game is a <code>shell.txt</code> file. In this situation you can wait a bit, and type flush again.</p><p>Another problem is hardline entering. During this process you can&#39;t type commands. To enter a hardline, type <code>kernel.hardline</code>, wait a bit, start spamming 1234567890 to enter the numbers on the screen, wait a bit, type flush to verify that you can type commands again. If at any step of this process something goes wrong you once again need to implement timeout logic to retry whatever you were doing.</p><p>Here&#39;s a list of things you can&#39;t do with the flush method</p><ul><li>Know if the terminal is currently processing a command</li><li>Get the contents of the shell without typing anything</li><li>Get the hardline timer or any other hardline game state parameters</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>While this method does have limitations, they are not so bad. You can find workarounds for all of them. In fact, before writing <code>hacked mud</code> I used this method and achieved very good results. Memory reading is a flex. It is for power users. It is for cases when 90% stability is not enough and you need the full 100%.</p>`,11))])}const w=i(c,[["render",d]]);export{_ as __pageData,w as default};
